export const getToolBySlug = (slug: string): ToolRegistryEntry | undefined =>
  toolsRegistry.find((t) => t.slug === slug);

export const toolsByCategory = (category: string): ToolRegistryEntry[] =>
  category === 'All' ? toolsRegistry : toolsRegistry.filter((t) => t.category === category);
